  IDNAError,
  invalidCodePointMessage,
  joinerContextMessage,
} from "./idna_errors.mjs";

const MARK_PATTERN = /^\p{Mark}$/u;
const UPPERCASE_PATTERN = /^(?:\p{Lu}|\p{Lt})$/u;
const ALLOWED_UNICODE_PATTERN = /^(?:[a-z0-9]|\p{Ll}|\p{Lo}|\p{Lm}|\p{Mn}|\p{Mc}|\p{Nd})$/u;

function throwInvalidCodePoint(character, position, label) {
  throw new IDNAError(
    invalidCodePointMessage(character.codePointAt(0), position, label),
  );
}

export function isAscii(value) {
  for (let index = 0; index < value.length; index += 1) {
    if (value.charCodeAt(index) > 0x7f) {
      return false;
    }
  }
  return true;
}

export function validateHyphenRules(label, allowAcePrefix = false) {
  if (label.startsWith("-") || label.endsWith("-")) {
    throw new IDNAError("Label must not start or end with a hyphen");
  }

  if (
    label.length >= 4 &&
    label[2] === "-" &&
    label[3] === "-" &&
    !(allowAcePrefix && label.slice(0, 4).toLowerCase() === "xn--")
  ) {
    throw new IDNAError("Label has disallowed hyphens in 3rd and 4th position");
  }
}

export function validateAsciiLabel(label, allowAcePrefix = false) {
  if (label.length === 0) {
    throw new IDNAError("Empty Label");
  }

  validateHyphenRules(label, allowAcePrefix);

  for (let index = 0; index < label.length; index += 1) {
    const character = label[index];
    if (!/[A-Za-z0-9-]/.test(character)) {
      throwInvalidCodePoint(character, index + 1, label);
    }
  }

  if (label.length > 63) {
    throw new IDNAError("Label too long");
  }
}

export function validateUnicodeLabel(label) {
  if (label.length === 0) {
    throw new IDNAError("Empty Label");
  }

  validateHyphenRules(label);

  const characters = Array.from(label);

  if (MARK_PATTERN.test(characters[0])) {
    throw new IDNAError("Label begins with an illegal combining character");
  }

  if (label.normalize("NFC") !== label) {
    throw new IDNAError("Label must be in Normalization Form C");
  }

  for (let index = 0; index < characters.length; index += 1) {
    const character = characters[index];
    const codePoint = character.codePointAt(0);

    if (character === "-") {
      continue;
    }

    if (codePoint === 0x200c || codePoint === 0x200d) {
      throw new IDNAError(joinerContextMessage(codePoint, index + 1, label));
    }

    if (UPPERCASE_PATTERN.test(character)) {
      throwInvalidCodePoint(character, index + 1, label);
    }

    if (character.normalize("NFKC") !== character) {
      throwInvalidCodePoint(character, index + 1, label);
    }

    if (!ALLOWED_UNICODE_PATTERN.test(character)) {
      throwInvalidCodePoint(character, index + 1, label);
    }
  }
}

