const BASE = 36;
const T_MIN = 1;
const T_MAX = 26;
const SKEW = 38;
const DAMP = 700;
const INITIAL_BIAS = 72;
const INITIAL_N = 128;
const DELIMITER = "-";

function basicToDigit(codePoint) {
  if (codePoint >= 0x30 && codePoint <= 0x39) {
    return codePoint - 22;
  }
  if (codePoint >= 0x41 && codePoint <= 0x5a) {
    return codePoint - 0x41;
  }
  if (codePoint >= 0x61 && codePoint <= 0x7a) {
    return codePoint - 0x61;
  }
  return BASE;
}

function digitToBasic(digit) {
  if (digit < 26) {
    return String.fromCharCode(0x61 + digit);
  }
  return String.fromCharCode(0x16 + digit);
}

function adapt(delta, numPoints, firstTime) {
  let nextDelta = firstTime ? Math.floor(delta / DAMP) : delta >> 1;
  nextDelta += Math.floor(nextDelta / numPoints);

  let k = 0;
  while (nextDelta > Math.floor(((BASE - T_MIN) * T_MAX) / 2)) {
    nextDelta = Math.floor(nextDelta / (BASE - T_MIN));
    k += BASE;
  }

  return k + Math.floor(((BASE - T_MIN + 1) * nextDelta) / (nextDelta + SKEW));
}

function toCodePoints(value) {
  return Array.from(value, (character) => character.codePointAt(0));
}

export function decodeBootstring(input) {
  let n = INITIAL_N;
  let i = 0;
  let bias = INITIAL_BIAS;
  const output = [];

  const delimiterIndex = input.lastIndexOf(DELIMITER);
  let index = 0;

  if (delimiterIndex >= 0) {
    for (let position = 0; position < delimiterIndex; position += 1) {
      const codePoint = input.charCodeAt(position);
      if (codePoint >= 0x80) {
        throw new Error("Invalid basic code point");
      }
      output.push(codePoint);
    }
    index = delimiterIndex + 1;
  }

  while (index < input.length) {
    const oldI = i;
    let weight = 1;

    for (let k = BASE; ; k += BASE) {
      if (index >= input.length) {
        throw new Error("Incomplete bootstring input");
      }

      const digit = basicToDigit(input.charCodeAt(index));
      index += 1;

      if (digit >= BASE) {
        throw new Error("Invalid bootstring digit");
      }

      i += digit * weight;

      const threshold =
        k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

      if (digit < threshold) {
        break;
      }

      weight *= BASE - threshold;
    }

    const outputLength = output.length + 1;
    bias = adapt(i - oldI, outputLength, oldI === 0);
    n += Math.floor(i / outputLength);
    i %= outputLength;

    output.splice(i, 0, n);
    i += 1;
  }

  return String.fromCodePoint(...output);
}

export function encodeBootstring(input) {
  const codePoints = toCodePoints(input);
  let n = INITIAL_N;
  let delta = 0;
  let bias = INITIAL_BIAS;
  let output = "";

  for (const codePoint of codePoints) {
    if (codePoint < 0x80) {
      output += String.fromCharCode(codePoint);
    }
  }

  const basicLength = output.length;
  let handledCount = basicLength;

  if (basicLength > 0) {
    output += DELIMITER;
  }

  while (handledCount < codePoints.length) {
    let minimum = Number.MAX_SAFE_INTEGER;

    for (const codePoint of codePoints) {
      if (codePoint >= n && codePoint < minimum) {
        minimum = codePoint;
      }
    }

    delta += (minimum - n) * (handledCount + 1);
    n = minimum;

    for (const codePoint of codePoints) {
      if (codePoint < n) {
        delta += 1;
      }

      if (codePoint === n) {
        let q = delta;

        for (let k = BASE; ; k += BASE) {
          const threshold =
            k <= bias ? T_MIN : k >= bias + T_MAX ? T_MAX : k - bias;

          if (q < threshold) {
            break;
          }

          output += digitToBasic(
            threshold + ((q - threshold) % (BASE - threshold)),
          );
          q = Math.floor((q - threshold) / (BASE - threshold));
        }

        output += digitToBasic(q);
        bias = adapt(delta, handledCount + 1, handledCount === basicLength);
        delta = 0;
        handledCount += 1;
      }
    }

    delta += 1;
    n += 1;
  }

  return output;
}

