import { formatPythonString } from "./python_format.mjs";

export class IDNAError extends Error {
  constructor(message) {
    super(message);
    this.name = "IDNAError";
  }
}

export function formatCodePoint(codePoint) {
  return `U+${codePoint.toString(16).toUpperCase().padStart(4, "0")}`;
}

export function invalidCodePointMessage(codePoint, position, label) {
  return `Codepoint ${formatCodePoint(codePoint)} at position ${position} of ${formatPythonString(label)} not allowed`;
}

export function joinerContextMessage(codePoint, position, label) {
  return `Unknown codepoint adjacent to joiner ${formatCodePoint(codePoint)} at position ${position} in ${formatPythonString(label)}`;
}

