import { decodeBootstring, encodeBootstring } from "./bootstring.mjs";
import { IDNAError } from "./idna_errors.mjs";
import {
  isAscii,
  validateAsciiLabel,
  validateUnicodeLabel,
} from "./idna_validation.mjs";

function normalizeInput(value) {
  if (Buffer.isBuffer(value)) {
    return value.toString("ascii");
  }
  return String(value);
}

function isAceLabel(label) {
  return label.length >= 4 && label.slice(0, 4).toLowerCase() === "xn--";
}

function decodeAceLabel(label) {
  const payload = label.slice(4);

  if (payload.length === 0) {
    throw new IDNAError("Malformed A-label, no Punycode eligible content found");
  }

  try {
    return decodeBootstring(payload);
  } catch (error) {
    throw new IDNAError("Malformed A-label, no Punycode eligible content found");
  }
}

export function alabel(value) {
  const label = normalizeInput(value);

  if (isAscii(label)) {
    if (isAceLabel(label)) {
      const decoded = decodeAceLabel(label);
      validateUnicodeLabel(decoded);
      if (label.length > 63) {
        throw new IDNAError("Label too long");
      }
      return Buffer.from(label, "ascii");
    }

    validateAsciiLabel(label);
    return Buffer.from(label, "ascii");
  }

  validateUnicodeLabel(label);

  const aceLabel = `xn--${encodeBootstring(label)}`;
  if (aceLabel.length > 63) {
    throw new IDNAError("Label too long");
  }

  return Buffer.from(aceLabel, "ascii");
}

export function ulabel(value) {
  const label = normalizeInput(value);

  if (isAceLabel(label)) {
    const decoded = decodeAceLabel(label);
    validateUnicodeLabel(decoded);
    return decoded;
  }

  if (isAscii(label)) {
    validateAsciiLabel(label);
    return label.toLowerCase();
  }

  validateUnicodeLabel(label);
  return label;
}

export function encode(value, options = {}) {
  const domain = normalizeInput(value);
  const strict = Boolean(options.strict);
  void strict;

  if (domain.length === 0) {
    throw new IDNAError("Empty domain");
  }

  const hasTrailingDot = domain.endsWith(".");
  const labels = domain.split(".");

  if (hasTrailingDot) {
    labels.pop();
  }

  const encodedLabels = labels.map((label) => alabel(label).toString("ascii"));
  const result = encodedLabels.join(".") + (hasTrailingDot ? "." : "");

  return Buffer.from(result, "ascii");
}

export function uts46Remap(value) {
  return normalizeInput(value)
    .replace(/[.\u3002\uFF0E\uFF61]/gu, ".")
    .normalize("NFKC")
    .toLowerCase()
    .normalize("NFC");
}

export function validStringLength(value, trailingDot = false) {
  const limit = trailingDot ? 254 : 253;
  return Array.from(normalizeInput(value)).length <= limit;
}

export const core = { IDNAError };
export { IDNAError };
export { uts46Remap as uts46_remap, validStringLength as valid_string_length };

export default {
  IDNAError,
  alabel,
  core,
  encode,
  ulabel,
  uts46_remap: uts46Remap,
  valid_string_length: validStringLength,
};

