import { CliExit, parseArgs, scriptNameFromPath } from "./lib/cli.mjs";
import {
  IDNAError,
  alabel,
  encode,
  ulabel,
  uts46_remap,
  valid_string_length,
} from "./lib/idna.mjs";
import {
  formatPythonBoolean,
  formatPythonBytes,
} from "./lib/python_format.mjs";

function writeStdout(line) {
  process.stdout.write(`${line}\n`);
}

function printValue(value) {
  if (Buffer.isBuffer(value)) {
    writeStdout(formatPythonBytes(value));
    return;
  }

  if (typeof value === "boolean") {
    writeStdout(formatPythonBoolean(value));
    return;
  }

  writeStdout(String(value));
}

function main() {
  const programName = scriptNameFromPath(process.argv[1]);
  let args;

  try {
    args = parseArgs(process.argv.slice(2), programName);
  } catch (error) {
    if (error instanceof CliExit) {
      if (error.stream === "stdout") {
        process.stdout.write(error.output);
      } else {
        process.stderr.write(error.output);
      }
      process.exit(error.code);
    }
    throw error;
  }

  const domain = args.domain;
  const strictMode = args.strict;

  if (strictMode) {
    try {
      printValue(encode(domain, { strict: true }));
    } catch (error) {
      if (error instanceof IDNAError) {
        printValue(`strict_encode_error: ${error.message}`);
      } else {
        throw error;
      }
    }
  } else {
    printValue(encode(domain, { strict: false }));
  }

  const remapped = uts46_remap(domain);
  printValue(remapped);

  const isValid = valid_string_length(remapped, false);
  printValue(isValid);

  const firstLabel = domain.split(".")[0];
  if (firstLabel) {
    try {
      const encodedFirst = encode(firstLabel);
      printValue(ulabel(encodedFirst));
      printValue(alabel(firstLabel));
    } catch {
      // The source script ignores any helper-label failure.
    }
  }
}

main();

