export class CliExit extends Error {
  constructor(code, output, stream) {
    super(output);
    this.name = "CliExit";
    this.code = code;
    this.output = output;
    this.stream = stream;
  }
}

const LONG_OPTIONS = ["help", "domain", "strict"];

export function scriptNameFromPath(pathname) {
  const source = String(pathname || "test3.mjs");
  const parts = source.split(/[/\\]/u);
  return parts[parts.length - 1] || "test3.mjs";
}

export function usageText(programName) {
  return `usage: ${programName} [-h] --domain DOMAIN --strict STRICT`;
}

export function helpText(programName) {
  return `${usageText(programName)}\n\noptions:\n  -h, --help       show this help message and exit\n  --domain DOMAIN\n  --strict STRICT\n`;
}

function errorText(programName, message) {
  return `${usageText(programName)}\n${programName}: error: ${message}\n`;
}

function resolveLongOption(name) {
  const matches = LONG_OPTIONS.filter((option) => option.startsWith(name));
  if (matches.length === 1) {
    return matches[0];
  }
  return null;
}

function throwHelp(programName) {
  throw new CliExit(0, helpText(programName), "stdout");
}

function throwError(programName, message) {
  throw new CliExit(2, errorText(programName, message), "stderr");
}

export function parseArgs(argv, programName) {
  let domain;
  let strict;
  let sawDomain = false;
  let sawStrict = false;
  const unknown = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === "--") {
      unknown.push(...argv.slice(index));
      break;
    }

    if (token.startsWith("--")) {
      const equalsIndex = token.indexOf("=");
      const optionName =
        equalsIndex === -1 ? token.slice(2) : token.slice(2, equalsIndex);
      const resolved = resolveLongOption(optionName);

      if (resolved === null) {
        unknown.push(token);
        continue;
      }

      if (resolved === "help") {
        if (equalsIndex !== -1) {
          const explicitValue = token.slice(equalsIndex + 1);
          throwError(
            programName,
            `argument -h/--help: ignored explicit argument '${explicitValue}'`,
          );
        }
        throwHelp(programName);
      }

      if (equalsIndex !== -1) {
        const value = token.slice(equalsIndex + 1);
        if (resolved === "domain") {
          domain = value;
          sawDomain = true;
        } else {
          strict = value;
          sawStrict = true;
        }
        continue;
      }

      const next = argv[index + 1];
      if (next === undefined || (next.startsWith("-") && next.length > 0)) {
        throwError(programName, `argument --${resolved}: expected one argument`);
      }

      if (resolved === "domain") {
        domain = next;
        sawDomain = true;
      } else {
        strict = next;
        sawStrict = true;
      }

      index += 1;
      continue;
    }

    if (token === "-h" || (token.startsWith("-h") && !token.startsWith("--"))) {
      throwHelp(programName);
    }

    unknown.push(token);
  }

  const missing = [];
  if (!sawDomain) {
    missing.push("--domain");
  }
  if (!sawStrict) {
    missing.push("--strict");
  }

  if (missing.length > 0) {
    throwError(
      programName,
      `the following arguments are required: ${missing.join(", ")}`,
    );
  }

  if (unknown.length > 0) {
    throwError(programName, `unrecognized arguments: ${unknown.join(" ")}`);
  }

  return {
    domain,
    strict: Boolean(strict),
  };
}
